"""The support chain of a manipulation step: which surface it works on and how high the grasp point is (David 2026-10-23, addendum G1 and G2; decisions-log M174).

    info = step_support(world, "pick", {"manipulated": beaker_entry}, phrase="the beaker")     # at grounding, per manipulation step
    info["surface"], info["support_chain"], info["target_height"]
    method = stance_method(info, world, phrase, cfg=BENCH_STANCE_CFG)                        # which stance method serves it, or a stop

A world-model entry may have `supported_by` (the id of the entry it stands on); a surface root (the bench) has none and `surface: True` and `top_z`. The world model supplies all of this; the LLM does not.
  chain       the entries from the object to the root: for a pick, the object's own; for a place, the destination's, with the object's base resting on the destination's top.
  top of an entry   the root's top_z, plus the `height` of every entry between the root and it, itself included.
  target height     the grasp point's height above the floor: the top of what the object stands on + the grasp-height fraction (PICK_PLACE_CFG["grasp_height_frac"]) of the object's height (a place adds
                    the set-down gap (PICK_PLACE_CFG["setdown_gap_m"])).
A step whose object is in the hand and has no destination to put it on has the surface "held": it never forms a stance run on its own (logged, nothing further is built).

Stops (the reason is the message; same style as the grounding's): "surface unknown: <phrase>" (no chain), "support chain does not end at a surface: <entry>" (a loop or a missing entry), "target height
outside the reach band: <phrase> at <z> m, band <a> to <b> m" (the band is the measured one of BENCH_STANCE_CFG["reach_band_file"]), "no stance method for surface: <name>" and "no stance method: <phrase> is <h> m
above the bench top, limit <limit> m" (stance_method). The check of the reach band and of the raise needs absolute heights, so it only runs when the world model knows the bench's height (top_z_known).

Contents:
    SupportError, support_chain, top_of, step_support, reach_band, stance_method, band_points, same_surface_runs, is_null_step.
"""

import json
from pathlib import Path

from src.task_config import BENCH_STANCE_CFG, PICK_PLACE_CFG

PROJECT_ROOT = Path(__file__).resolve().parents[1]


class SupportError(ValueError):
    """A step that has no usable surface or target height; the message is the reason the plan stops with."""


def _get(world, entry_id):
    try:
        return world.get(entry_id)
    except Exception:                                              # noqa: BLE001 - the world model's own error for an unknown id
        return None


def support_chain(world, entry, phrase=None):
    """The entries from `entry` to its surface root, `entry` first.

    Raises:
        SupportError: "surface unknown: <phrase>" when the entry has no support and is not a surface root; "support chain does not end at a surface: <id>" for a loop or a missing entry.
    """
    chain, seen, cur = [entry], {entry.id}, entry
    while not cur.properties.get("surface"):
        nxt_id = cur.properties.get("supported_by")
        if nxt_id is None:
            if cur is entry:
                raise SupportError(f"surface unknown: {phrase or entry.name}")
            raise SupportError(f"support chain does not end at a surface: {cur.id}")
        nxt = _get(world, nxt_id)
        if nxt is None or nxt.id in seen:
            raise SupportError(f"support chain does not end at a surface: {nxt_id}")
        chain.append(nxt)
        seen.add(nxt.id)
        cur = nxt
    return chain


def top_of(chain, index=0):
    """The height of the top of chain[index] above the floor: the root's top_z plus the heights of the entries from the root up to and including it."""
    root = chain[-1]
    z = float(root.properties["top_z"])
    for e in reversed(chain[index:-1]):
        z += float(e.properties.get("height", 0.0))
    return z


def step_support(world, primitive, resolved, phrase=None, cfg=PICK_PLACE_CFG):
    """The support information of a grounded manipulation step.

    Args:
        world (WorldModel): The knowledge base.
        primitive (str): "pick", "place" or "other".
        resolved (dict): {role: Entry} from the grounding ("manipulated", maybe "destination").
        phrase (str or None): The step's object phrase, for the stop messages.
        cfg (dict): PICK_PLACE_CFG.

    Returns:
        dict or None: {"surface" (the root's name, or "held"), "support_chain" (names, object or destination first), "target_height" (m above the floor, None for "held"), "known_height" (bool: absolute
        heights are known)}; None when the world model has no support information at all (no entry has supported_by or surface: nothing is added to the step).

    Raises:
        SupportError: See the module docstring.
    """
    if not any(e.properties.get("supported_by") is not None or e.properties.get("surface") for e in world.entries()):
        return None
    obj = resolved.get("manipulated")
    dest = resolved.get("destination")
    if primitive == "place" and dest is not None:
        chain = support_chain(world, dest, phrase or dest.name)
        rest = top_of(chain, 0)
        gap = cfg["setdown_gap_m"]
    else:
        if obj is None:
            raise SupportError(f"surface unknown: {phrase or 'the step has no object'}")
        if obj.properties.get("held_by"):
            return {"surface": "held", "support_chain": [obj.name], "target_height": None, "known_height": False}
        chain = support_chain(world, obj, phrase or obj.name)
        if len(chain) < 2:
            raise SupportError(f"surface unknown: {phrase or obj.name}")
        rest = top_of(chain, 1)
        gap = 0.0
    H = float(obj.properties.get("height", 0.0)) if obj is not None else 0.0
    known = bool(chain[-1].properties.get("top_z_known"))
    return {"surface": chain[-1].name, "support_chain": [e.name for e in chain], "target_height": rest + gap + cfg["grasp_height_frac"] * H, "known_height": known, "support_top": rest}


def reach_band(cfg=BENCH_STANCE_CFG):
    """The measured reach band (lowest, highest grasp-point height above the floor some stance can serve), or None when it has not been measured (BENCH_STANCE_CFG["reach_band_file"])."""
    f = cfg.get("reach_band_file")
    p = Path(f) if f is None else (Path(f) if Path(f).is_absolute() else PROJECT_ROOT / f)
    if f is None or not p.exists():
        return None
    d = json.loads(p.read_text())
    return float(d["min_over_q"]), float(d["max_over_q"])


def check_band(info, phrase, band=None):
    """Raises SupportError when the target height is outside the measured reach band (no pedestal height reaches it)."""
    band = reach_band() if band is None else band
    if info is None or info["surface"] == "held" or not info.get("known_height") or band is None:
        return
    z = info["target_height"]
    if not band[0] - 1e-9 <= z <= band[1] + 1e-9:
        raise SupportError(f"target height outside the reach band: {phrase} at {z:.3f} m, band {band[0]:.3f} to {band[1]:.3f} m")


def stance_method(info, world, phrase, cfg=BENCH_STANCE_CFG):
    """Which stance method serves a step (G2): the settings of its root surface, or a stop.

    Args:
        info (dict): From step_support.
        world (WorldModel): For the bench's top.
        phrase (str): The step's phrase, for the messages.
        cfg (dict): BENCH_STANCE_CFG.

    Returns:
        dict: {"method": "bench", "settings": cfg["surfaces"][surface], "raise_m": the grasp point's height above the bench top}.

    Raises:
        SupportError: "no stance method for surface: <name>" (a root with no settings; "held" included), or "no stance method: <phrase> is <h> m above the bench top, limit <limit> m".
    """
    s = cfg["surfaces"].get(info["surface"])
    if s is None:
        raise SupportError(f"no stance method for surface: {info['surface']}")
    bench_top = float(world.get(s["entry"]).properties["top_z"])
    raise_m = info["target_height"] - bench_top                                   # the grasp point's height above the bench top (G2)
    limit = cfg["bench_max_raise_m"]
    if info.get("known_height") and limit is not None and raise_m > limit + 1e-9:
        raise SupportError(f"no stance method: {phrase} is {raise_m:.3f} m above the bench top, limit {limit:.3f} m")
    return {"method": "bench", "settings": s, "raise_m": raise_m}


def band_points(target_height, object_height, band, step=0.05, grasp_frac=PICK_PLACE_CFG["grasp_height_frac"]):
    """The grasp-band heights (world z) of a target whose grasp point (the band's middle) is at target_height: the band fractions of the object's height around it."""
    import numpy as np
    lo, hi = band
    return [float(target_height + (f - grasp_frac) * object_height) for f in np.arange(lo, hi + 1e-9, step)]


def same_surface_runs(infos, start, kmax=4):
    """The longest candidate run of consecutive manipulation steps from `start` that share a root surface (G2): the list of step indices (at most kmax, at least one).

    Args:
        infos (list): One per manipulation step in plan order: the step_support dict (or None).
        start (int): Index of the first step of the run.
        kmax (int): The most steps in a run. Defaults to 4.

    Returns:
        list of int: start, start + 1, ... while the root surface stays the same and is not "held".
    """
    first = infos[start]
    if first is None or first["surface"] == "held":
        return [start]
    run = [start]
    for j in range(start + 1, min(len(infos), start + kmax)):
        if infos[j] is None or infos[j]["surface"] != first["surface"]:
            break
        run.append(j)
    return run


def is_null_step(next_surface, current_surface):
    """A navigation step is null only when the next run's root surface is the current stance's (G2)."""
    return current_surface is not None and next_surface == current_surface and next_surface != "held"
